 javascript:`import { BoxOx } from '@boxox/mail';\n\nconst mail = new BoxOx({\n  url: process.env.BOXOX_URL,\n  key: process.env.BOXOX_KEY,\n});\n\nawait mail.messages.send({\n  from: 'hello@yourdomain.com',\n  to: 'customer@example.com',\n  subject: 'Your receipt',\n  text: 'Thank you for your order.',\n}, { idempotencyKey: 'receipt-123' });`,
