const downloadCards = `<div class="download-grid">${downloads.map(d=>`<article class="download-card"><div class="download-card-top"><span class="download-icon ${d.label?'language':''}">${d.label??icon(d.i)}</span><span class="version">v${d.version}</span></div><h3>${d.title}</h3><p>${d.text}</p><div class="download-command"><code>${esc(d.command)}</code><button type="button" aria-label="Copy ${d.title} command" data-copy-text="${esc(d.command)}">${icon('copy')}</button></div><a class="download-button" href="${d.url}" ${d.action?'':'download'}>${icon('down')}${d.action??'Download'}</a><small>${d.meta}</small></article>`).join('')}</div>`;
const agentLogos = `<div class="agent-clients"><p>Bring your coding agent</p><ul class="agent-logos" aria-label="Coding agents">${[['openai.png','Codex','Codex by OpenAI'],['claude.png','Claude','Claude by Anthropic'],['gemini.png','Gemini','Gemini CLI by Google'],['cursor.svg','Cursor','Cursor'],['copilot.svg','Copilot','GitHub Copilot']].map(([file,name,label])=>`<li title="${label}"><img src="/integrations/${file}" width="28" height="28" alt=""><span>${name}</span></li>`).join('')}</ul><p class="agent-note">The runbook is plain Markdown. Any coding agent that can run shell commands and Wrangler can follow it; these are examples, not a tested list.</p></div>`;
const downloadPage = `<section class="hero downloads-hero"><div class="container hero-grid"><div class="hero-copy"><p class="pill">${icon('cloud')} DOWNLOADS</p><h1>The app, the tools,<br>and the agent runbook.</h1><p class="hero-description">The app, SDK, CLI, and agent tools for building email workflows on Cloudflare. Download them here. Run them in your account.</p><div class="actions">${button('Let your agent install','/downloads/#agent-install','primary','data-agent-install-cta')}${button('Download the project','/downloads/boxox-v2.zip','secondary','download')}</div>${ticks}</div><div class="download-visual"><div class="download-window"><strong>${icon('terminal')} Download Box Ox</strong>${[['code','SDK + CLI','Build and automate'],['cloud','Cloudflare project','Deploy in your account'],['bot','Agent tools','Install and integrate'],['logs','API resources','Contracts and examples'],['box','Brand assets','Meet your ox']].map(([i,t,d])=>`<div>${icon(i)}<span><b>${t}</b><small>${d}</small></span>${icon('down')}</div>`).join('')}</div><img src="/brand/mascot-downloads-v2.webp" width="1100" height="825" fetchpriority="high" alt="Box Ox with a laptop, envelope, and boxes of developer tools"></div></div><div class="cloud-edge" aria-hidden="true"></div></section>${stack}<div class="container requirement-strip"><strong>Before you install:</strong> Box Ox is free. One installer fits your Cloudflare plan: an inbox on Workers Free, or the full app on Workers Paid. R2 is required. Add a domain when you are ready to send or receive mail. Cloudflare bills any usage charges. <a href="/requirements/">Compare Free and Paid requirements →</a></div><section class="container section" id="developer-tools"><div class="section-top"><div>${eyebrow('DOWNLOADS')}<h2>Official tools.<br>Ready for your workflow.</h2></div><p>Packages are self-published by Box Ox. Download the files, verify the checksums, and use your preferred tools.</p></div>${downloadCards}<p class="download-note"><a href="/downloads/SHA256SUMS.txt">Release SHA-256 checksums</a> · <a href="/downloads/release.json">Release metadata</a> · <a href="/downloads/boxox-cli-0.2.0.tgz">Installable CLI tarball</a> · <a href="/downloads/RESOURCE-SHA256SUMS.txt">Resource checksums</a></p></section><section class="container agent-section" id="agent-install"><div>${eyebrow('LET YOUR AGENT HANDLE SETUP')}<h2>Your agent can<br>take it from here.</h2><p>Copy this link into your agent’s chat. It covers account checks, deployment, owner access, mail-domain setup, and verification.</p></div><div class="agent-copy-box">${agentLogos}<label for="agent-install-link">Agent installation guide</label><input id="agent-install-link" type="url" value="https://boxox.dev/install-agent.md" readonly><button class="button primary" type="button" data-copy-agent-link="https://boxox.dev/install-agent.md" aria-describedby="agent-copy-status">Copy agent install link ${icon('copy')}</button><p id="agent-copy-status" data-agent-copy-status role="status"></p><div data-agent-copy-fallback hidden><p>Select and copy the link above, or <a href="/install-agent.md">open the guide</a>.</p></div><noscript><a href="/install-agent.md">Read and copy the agent guide URL</a></noscript><small>Your agent needs Cloudflare authorization, plan verification, and your mail-domain choices.</small></div></section>${developerSection(true)}<section class="container section"><div class="section-top"><div>${eyebrow('PLATFORM SUPPORT')}<h2>One SDK. Your environment.</h2></div><p>The web app and remote MCP run on Cloudflare. The CLI runs on your computer or in your automation environment.</p></div><div class="table-wrap"><table><thead><tr><th>Environment</th><th>Tool</th><th>Version</th><th>Requirements</th><th>Get started</th></tr></thead><tbody>${[['Node.js','@boxox/mail','0.2.0','Fetch + Web Crypto','/downloads/boxox-mail-0.2.0.tgz'],['Cloudflare Workers','@boxox/mail','0.2.0','Workers runtime','/downloads/boxox-mail-0.2.0.tgz'],['Terminal / CI','Box Ox CLI','0.2.0','Node.js 22+','/downloads/boxox-cli-0.2.0.mjs'],['Self-hosted app','Box Ox',APP_VERSION,'Workers Free or Paid + Access','/downloads/boxox-v2.zip'],['Agents','Remote MCP',APP_VERSION,'Your Box Ox installation','/install-agent.md']].map(r=>`<tr><td>${r[0]}</td><td><code>${r[1]}</code></td><td>v${r[2]}</td><td>${r[3]}</td><td><a href="${r[4]}">Get the tool ${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div></section>${releaseSection()}${support}${cta}`;
function releaseSection(){
  const entries=[
    ['cloud','Box Ox',APP_VERSION,RELEASE_DATE,'Requested mailbox access and clear MCP consent feedback.',`/docs/releases/${APP_VERSION}/`],
    ['code','Typed SDK','0.2.0','2026-10-19','The developer API client and signed-webhook verifier.','/docs/releases/2.4.0/'],
    ['terminal','Box Ox CLI','0.2.0','2026-10-19','Keys, messages, templates, and local webhook forwarding.','/docs/releases/2.4.0/'],
    ['bot','Email skill',EMAIL_SKILL_VERSION,'2026-10-19','A reusable application integration workflow for your agent.',`/docs/releases/${APP_VERSION}/`],
  ];
  return `<section class="container section releases"><div class="section-top"><div>${eyebrow('RECENT RELEASES')}<h2>What’s new.</h2></div><a href="/releases/">View release notes ${icon('arrow')}</a></div><div class="release-grid">${entries.map(([i,t,v,date,d,href])=>`<article>${icon(i)}<div><h3>${t} <span>v${v}</span></h3><time datetime="${date}">${new Date(date).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'})}</time><p>${d}</p><a href="${href}">Release details ${icon('arrow')}</a></div></article>`).join('')}</div></section>`;
}
const prosePage = (title,intro,content,tag='BOX OX',level=1) => `<section class="page-hero container">${eyebrow(tag)}<h${level}>${title}</h${level}><p>${intro}</p></section><section class="container prose-layout"><article class="prose">${content}</article><aside class="help-aside">${icon('mail')}<h3>Need a hand?</h3><p>Ask about setup, report a problem, or send feedback.</p><a href="mailto:hello@boxox.dev">hello@boxox.dev ${icon('arrow')}</a><hr><a href="/docs/">Documentation</a><a href="/downloads/">Downloads</a><a href="/security/">Security & privacy</a></aside></section>`;
const pages = {
 ...comparisonPages({button, eyebrow}),
 '/screenshots/':{title:'Box Ox screenshots — Inbox, domains & developer tools',description:'Browse screenshots of the Box Ox mail client, search, domain controls, processing settings, scoped API keys, message logs, and webhooks using fictional demo mail.',body:screenshotsPage()},
 '/':{title:'Box Ox — Email API and reply inbox for Cloudflare Workers apps',description:'Free, self-installed transactional email API and threaded inbox for apps on Cloudflare Workers. Scoped keys, templates, signed webhooks, and revocable agent access.',body:home},
 '/downloads/':{title:'Download Box Ox — SDK, CLI, Cloudflare project & agent tools',description:'Download the self-hosted Box Ox app, JavaScript and TypeScript SDK, standalone CLI, agent skill, OpenAPI specification, and brand assets. Direct downloads, no npm registry.',body:downloadPage},
 '/features/':{title:'Box Ox features — Mail, transactional email API & agent access',description:'Explore Box Ox threaded mail, transactional API, templates, signed webhooks, message logs, and scoped MCP agent access in your own Cloudflare account.',body:`<section class="page-hero container">${eyebrow('ONE INSTALLATION. YOUR DOMAINS.')}<h1>Send from your app.<br>Read the replies.</h1><p>Send application mail, read incoming messages, and connect your agents without moving the installation out of your Cloudflare account.</p></section><section class="container section">${featureCards()}</section>${prosePage('A closer look.','Choose the parts your application needs.',`<h2 id="mail">A browser inbox for your domains’ mail</h2><p>Threads, labels, search, attachments, compose, scheduled sends, spam controls, and a Sent view. Successful developer API sends also get mailbox copies. Outbound mail uses Cloudflare Email Service, which Cloudflare’s terms cover for transactional sending; confirm with Cloudflare before relying on it for everyday conversational replies. You can add domains after setup, review their DNS, and create personal, role, agent, or disposable addresses.</p><h2 id="developers">Transactional email for applications</h2><p>Use domain-scoped API keys, idempotent requests, reusable templates, delivery timelines, suppressions, and signed webhooks. Optional open and click tracking starts off. Logs show individual message events; Box Ox does not include an aggregate mail-performance dashboard.</p><h2 id="agents">Agent access with boundaries</h2><p>The remote MCP endpoint runs on your Worker. OAuth approval, mailbox grants, sending caps, and revocation control what each agent can do. The downloadable CLI and email skill help agents integrate your applications. Mail MCP access does not grant Cloudflare account administration.</p><h2>Processing stays your choice</h2><p>Local filters, reputation checks, and AI are separate settings. AI remains off until you choose it. External providers receive selected content when enabled. <a href="/security/">Read the data-flow details.</a></p>`,'FEATURE DETAILS',2)}${cta}`},
 '/how-it-works/':{title:'How Box Ox works — Your mail on Cloudflare',description:'See how the Box Ox Worker, D1 metadata, R2 mail storage, Email Service, Access, webhooks, and agents fit together in your own Cloudflare account.',body:`<section class="page-hero container">${eyebrow('YOUR ACCOUNT, ALL THE WAY DOWN.')}<h1>How the pieces fit.<br>In your account.</h1><p>Box Ox is the app and API. Cloudflare supplies the runtime, mail transport, storage, and owner sign-in.</p></section>${workflow}${prosePage('From install to inbox.','You choose the account, domains, and permissions.',`<h2>1. Deploy your installation</h2><p>Download the project or give the guide to your agent. The deployment helper provisions the declared resources and applies migrations. The app can use your free workers.dev address or an optional custom hostname.</p><h2>2. Protect owner access</h2><p>Configure Cloudflare Access for your chosen hostname and owner identity. Owner APIs fail closed before Access is configured. Credential-protected developer and agent endpoints use the exact public protocol exceptions described in the setup guide.</p><h2>3. Connect a mail domain</h2><p>Your email domain must be on Cloudflare DNS. Choose sending only to keep existing receiving records, or preview and confirm receiving changes. Receiving uses Email Routing to reach your Worker; stored mail goes to R2 and metadata to D1.</p><h2>4. Connect your application or agent</h2><p>Applications send through a domain-scoped key. Delivery events reach Cloudflare Queues and update Box Ox logs and signed webhooks. Agents use your Worker’s MCP or agent API, with grants you can revoke.</p><h2>What runs where?</h2><ul><li><strong>Cloudflare:</strong> the app, API, remote MCP, workflows, mail storage, database, and mail transport.</li><li><strong>Your computer or CI:</strong> the CLI, deployment tools, and local development.</li><li><strong>Boxox.dev:</strong> this public website, downloads, and documentation.</li></ul><p>${button('Open the setup guide','/setup/')}</p>`,'INSTALLATION',2)}${cta}`},
 '/pricing/':{title:'Box Ox pricing — No subscription, Cloudflare bills your usage',description:'Box Ox has no subscription fee. Compare Cloudflare Workers Free and Paid: full Box Ox requires Workers Paid from $5/month per account, billed directly by Cloudflare.',body:pricingPage({mark,button,icon,cta})},
 '/about/':{title:'About Box Ox — Mail infrastructure you run yourself',description:'Box Ox brings a mail client, transactional email API, and scoped agent access together in an installation you run in your own Cloudflare account.',body:prosePage('A little more yours.','The mail layer for an app you already run on Cloudflare.',`<h2>Why Box Ox exists</h2><p>Your applications need to send mail. Your domains need somewhere for incoming messages to go. Your agents need access that you can understand and revoke.</p><p>Box Ox brings those pieces into one installation: a browser mail client, a transactional email API, and scoped agent access. It runs on Cloudflare services in your account.</p><h2>Built for people who build</h2><p>The starting point is a developer or small team whose app already runs on Cloudflare Workers and needs to send mail and hear back. You control deployment, domains, data, and ongoing maintenance. Box Ox supplies the application and integration tools.</p><h2>Independently maintained</h2><p>Box Ox is published by <a href="https://khuur.dev">Khuur.dev</a> with contributions from the Box Ox project. It is independent of Cloudflare and is not an official Cloudflare product or an endorsed service.</p><h2>Source available, with clear terms</h2><p>The application uses FSL-1.1-MIT, with each version converting to MIT after two years. The SDK and CLI are MIT licensed. <a href="/license/">Read the license details.</a></p><p>Have a question, an idea, or a rough edge to report? <a href="/contact/">Get in touch.</a></p>`,'ABOUT BOX OX')},
 '/contact/':{title:'Contact Box Ox — Setup, feedback, security & licensing',description:'Contact the Box Ox maintainer at hello@boxox.dev for setup questions, bug reports, feedback, privacy requests, or licensing questions.',body:`<section class="page-hero container">${eyebrow('GET IN TOUCH')}<h1>Say hello to Box Ox.</h1><p>A setup question, an idea, or something that needs fixing?<br>We’d like to hear about it.</p></section><section class="container contact-grid"><div class="contact-copy"><div class="contact-email">${icon('mail')}<h2>Email us directly.</h2><a href="mailto:hello@boxox.dev">hello@boxox.dev</a><p>Published and maintained by Khuur.dev / Box Ox.</p></div><h3>Help us help you.</h3><p>For a bug, include the Box Ox version, what you expected, and the steps to reproduce it. Redact API keys, login codes, message content, and other private information.</p><p>For a security issue, email a short description first. Don’t send live credentials or sensitive mail samples.</p><p>There is no guaranteed support response time. <a href="/docs/">The docs</a> may have the answer you need.</p></div><form class="contact-form" data-contact-form action="/api/contact" method="post"><h2>Start a conversation.</h2><p>Send directly to our Box Ox inbox. We use your email address to reply.</p><label for="contact-name">Your name <span>(optional)</span></label><input id="contact-name" name="name" autocomplete="name" maxlength="100"><label for="contact-email">Your email</label><input id="contact-email" name="email" type="email" autocomplete="email" required maxlength="254"><div class="contact-honeypot" aria-hidden="true"><label for="contact-company">Leave this field empty</label><input id="contact-company" name="company" tabindex="-1" autocomplete="off"></div><label for="contact-topic">What’s it about?</label><select id="contact-topic" name="topic"><option>General question</option><option>Setup help</option><option>Bug report</option><option>Security report</option><option>Privacy request</option><option>Licensing</option></select><label for="contact-message">Your message</label><textarea id="contact-message" name="message" rows="6" required maxlength="8000" placeholder="Tell us what you’re working on…"></textarea><button class="button primary" type="submit">Send message ${icon('arrow')}</button><p class="form-status" role="status" data-contact-status></p><small>Prefer your own email app? Write directly to <a href="mailto:hello@boxox.dev">hello@boxox.dev</a>. <a href="/privacy/">Privacy notice</a></small></form></section>${cta}`},
 '/security/':{title:'Box Ox security & privacy — Access, grants and data flows',description:'Understand Cloudflare Access protection, scoped API keys, agent grants, optional AI processing, and the security responsibilities of a self-hosted Box Ox installation.',body:prosePage('Your account.<br>Clear boundaries.','Understand what Box Ox protects, what it processes, and what stays your responsibility.',`<h2>Owner access is separate</h2><p>The owner application uses Cloudflare Access. It fails closed until the required Access configuration is present. The developer API uses scoped domain keys. Agents use owner-approved OAuth/MCP clients or paired credentials and mailbox grants.</p><h2>Give each integration what it needs</h2><p>Domain keys can be restricted by permission, sender, recipient, expiry, rate, and sending budget. Mailbox grants, sending caps, a kill switch, and revocation limit agent access. Protect the management key and keep it out of application deployments.</p><h2>Mail storage is in your account</h2><p>R2 stores mail content and attachments; D1 stores metadata and events. Cloudflare and people with sufficient access to your account can access that data. Box Ox does not add end-to-end encryption or application-level mail encryption.</p><h2>AI starts off</h2><p>Local filters, reputation checks, and AI have separate controls. Enabling an external AI provider sends selected mail content to that provider through your AI Gateway. Provider and Cloudflare terms still apply. A zero-data-retention routing preference is not a guarantee of provider retention behavior.</p><h2>Operational visibility</h2><p>Cloudflare provides platform metrics and logs. Box Ox stores message outcomes, webhook attempts, and audit events. Open and click tracking is optional and off by default. Box Ox does not include an aggregate mail-performance dashboard.</p><h2>What the operator owns</h2><p>Configure Access and DNS carefully, protect account credentials, review updates, manage backups and retention, and test your installation. Removing the temporary setup token after onboarding reduces persistent administrative access.</p><h2>Report a vulnerability</h2><p>Email <a href="mailto:hello@boxox.dev?subject=Security%20report">hello@boxox.dev</a> with the affected version, an explanation, and safe reproduction steps. Do not include live API keys, passwords, or private mail. No response-time commitment or certification is implied.</p><p><a href="/privacy/">Website privacy notice</a> · <a href="/setup/">Setup guide</a></p>`,'SECURITY & PRIVACY')},
 '/privacy/':{title:'Box Ox privacy notice — Website, contact & self-hosted installs',description:'How boxox.dev handles website visits and contact emails, and how that differs from mail and data stored in your own self-hosted Cloudflare installation.',body:prosePage('Privacy notice.','Effective October 19, 2026. Publisher: Khuur.dev / Box Ox.',`<h2>Scope and contact</h2><p>This notice covers boxox.dev, its downloads and documentation, and messages you send to the project maintainer. Contact <a href="mailto:hello@boxox.dev">hello@boxox.dev</a> for privacy questions or requests.</p><h2>Visits to this website</h2><p>The public site is served through Cloudflare. Requests can include your IP address, browser and device information, requested URL, time, and technical information needed to serve and secure the website. Cloudflare processes request data to deliver its services; infrastructure metrics and logs may be available to the site operator.</p><p>The website does not sell subscriptions, accept payments, or create shared hosted-mail accounts. We do not use advertising pixels or a marketing mailing-list form. Optional website analytics is described below.</p><h2>Optional website analytics</h2><p>With your permission, Google Analytics measures visits to public pages, clicks on named download files, and successful copies of the agent installation link. It receives technical request information such as IP address and browser information, public page paths, referring-site origins, simple campaign tags, and the selected file or action. Google processes this data to provide analytics.</p><p>The Google tag is not loaded before you allow analytics. Declining keeps it off. Analytics does not receive contact form fields, email addresses entered in forms, mailbox content, API keys, or arbitrary URL queries and fragments from our tracking code. Advertising storage, Google Signals, and ad personalization are disabled. Enhanced measurement is off; file clicks and agent-link copies are sent explicitly.</p><p>We store your analytics choice in local browser storage for up to 180 days. If allowed, Google Analytics uses first-party cookies with a configured lifetime of up to 180 days. The property uses two-month event-data retention. Aggregated reports can be kept longer. Browser controls, deletion, or blocking can shorten storage.</p><p>Use <button type="button" class="inline-settings" data-analytics-settings>Analytics settings</button> to change your choice. Withdrawal stops future measurement and clears the site’s Google Analytics cookies; it does not automatically delete data already collected. We honor a detected Global Privacy Control signal by keeping optional analytics off. Contact us for applicable access or deletion requests. See <a href="https://policies.google.com/privacy">Google’s privacy policy</a> and <a href="https://support.google.com/analytics/answer/12017362">Google Analytics data collection information</a>.</p><h2>Contact messages</h2><p>The contact form sends your name (if supplied), reply email, topic, and message through our Box Ox installation on Cloudflare to hello@boxox.dev. We use these details to handle your request and reply. We also use request metadata, including IP addresses, to limit abuse. Do not submit credentials or private mailbox contents.</p><h2>Your self-hosted installation</h2><p>When you install Box Ox in your own Cloudflare account, your installation’s mail and metadata are stored in that account. The public Box Ox website is not a shared backend for those mailboxes, and installing the software does not grant the project maintainer access to your account or mail.</p><p>The installation operator controls identities, permissions, mail domains, retention, and optional processing. That operator is responsible for notices and data-protection obligations applicable to their use. Contact the relevant installation operator about mail they process.</p><h2>AI and other optional services</h2><p>AI is off until the installation owner enables it. Selected mail content is sent to a configured external provider when that provider is enabled. Reputation lookups and optional open/click tracking have separate data flows. Review the <a href="/docs/processing-settings.md">processing guide</a> and the providers’ current terms before enabling them.</p><h2>Sharing and service providers</h2><p>Cloudflare supplies the website infrastructure and the maintainer’s Box Ox mail infrastructure. A recipient’s email provider also handles contact correspondence. Information may be disclosed when needed to comply with law, respond to a valid legal request, protect security or rights, or provide services you request. We do not sell contact messages or use them for targeted advertising.</p><h2>Retention and security</h2><p>Technical data is retained according to the configured services and operational needs. Contact correspondence is retained while needed for its purpose, follow-up, security, or legal obligations, and reviewed when a deletion request is received. There is no fixed public retention period promised here. No method of storage or transmission is perfectly secure.</p><h2>Your choices and rights</h2><p>Where applicable law gives you access, correction, deletion, objection, portability, or other rights, contact hello@boxox.dev. We may need to verify the request and may retain information when permitted or required by law. You may also have a right to complain to your local data-protection authority. For a self-hosted installation, direct requests to its operator.</p><h2>International processing and updates</h2><p>Cloudflare and email services can process data outside your country. This site does not promise storage or processing exclusively in the United States or another location. We may update this notice as the site changes; the effective date will be updated for material changes.</p><p><a href="/cookies/">Cookie notice</a> · <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy policy</a></p>`,'LEGAL')},
 '/terms/':{title:'Box Ox website terms — Downloads, use & responsibilities',description:'Terms for the Box Ox public website and documentation, with links to the application license and the responsibilities of running your own Cloudflare installation.',body:prosePage('Website terms.','Effective October 18, 2026. Publisher: Khuur.dev / Box Ox.',`<h2>What this website provides</h2><p>Boxox.dev distributes Box Ox software, documentation, examples, and related resources. It does not provide a shared hosted-email account, managed Cloudflare account, or guaranteed email-delivery service.</p><h2>Software and asset licenses</h2><p>Your rights to use the application are governed by its included <a href="/license.txt">FSL-1.1-MIT license</a>, not a promise of unrestricted open-source use. The SDK and CLI include MIT licenses. Preserve applicable license and attribution notices. Third-party software and service terms apply separately.</p><p>Box Ox names and artwork identify this project. Do not use them to falsely suggest an official service, endorsement, partnership, or affiliation. Cloudflare and other third-party names belong to their respective owners.</p><h2>Running your own installation</h2><p>You are responsible for your Cloudflare account, service charges, domain and DNS configuration, credentials, access grants, stored data, backups, retention, lawful email use, and notices required for your users. Review updates and test the installation before relying on it. Cloudflare’s Email Service restrictions and other service terms apply.</p><h2>Acceptable use</h2><p>Do not use this website or distributed examples to facilitate spam, phishing, malware, unauthorized access, impersonation, or unlawful activity. Only send mail from domains and to recipients for which you have the required authorization. Do not probe or attack another person’s installation without permission.</p><h2>Accuracy, availability, and support</h2><p>Documentation and examples can contain errors or become outdated. Features, downloads, and this website may change or be unavailable. No support response time, service level, fitness for a particular use, compatibility, security certification, or delivery outcome is promised unless separately agreed in writing.</p><h2>Disclaimers and liability</h2><p>Website materials are provided “as is” and “as available” to the extent permitted by applicable law. Software warranties and liability are addressed by the applicable software license. Nothing in these terms excludes rights or liabilities that applicable law does not permit to be excluded.</p><h2>Third-party services and links</h2><p>Links to Cloudflare, providers, and other services are provided for convenience. Those services are operated under their own terms and policies. Box Ox is independently maintained and is not an official Cloudflare product.</p><h2>Contact and changes</h2><p>For questions, licensing, security, privacy, or a dispute, email <a href="mailto:hello@boxox.dev">hello@boxox.dev</a>. We may update these website terms; the effective date will identify the current version. An updated website notice does not rewrite the license included with an already distributed software version.</p>`,'LEGAL')},
 '/cookies/':{title:'Box Ox cookie notice — Public site & Cloudflare Access',description:'Learn about the Box Ox public website, local browser controls, and the separate cookies used by Cloudflare security and Access-protected installations.',body:prosePage('Cookie notice.','Effective October 18, 2026.',`<h2>The public website</h2><p>The public Box Ox pages do not require an application login or advertising cookies. Optional Google Analytics stays off until you allow it. Clipboard controls, code examples, documentation, and downloads work when you decline analytics.</p><h2>Analytics storage</h2><p>The local-storage key <code>boxox.analytics.v1</code> records your analytics choice and its expiry for up to 180 days. It is used to remember that choice, including a refusal. If you allow analytics, Google Analytics may set first-party <code>_ga</code> and <code>_ga_*</code> cookies for visitor and session measurement. Their configured lifetime is up to 180 days without automatic renewal. Advertising storage remains denied.</p><p>No Google Analytics script is loaded while your choice is unknown or declined. A detected Global Privacy Control signal also keeps it off. Withdraw through <button type="button" class="inline-settings" data-analytics-settings>Analytics settings</button>; the page disables measurement, clears these cookies, and reloads to unload the tag. Existing data already sent to Google is subject to the retention described in our privacy notice.</p><h2>Cloudflare services</h2><p>Cloudflare may use cookies or similar mechanisms when security, bot protection, challenges, or other configured services require them. Their use depends on the features operating on a request. See <a href="https://developers.cloudflare.com/fundamentals/reference/policies-compliances/cloudflare-cookies/">Cloudflare’s cookie documentation</a> for the services and cookie names it describes.</p><h2>Your separate Box Ox installation</h2><p>An Access-protected installation is separate from this public website. Cloudflare Access uses authentication cookies to manage sign-in. The installed app may use browser storage for preferences and tab-scoped developer credentials. The installation operator controls its configuration and should provide an appropriate notice.</p><p>The Add domain flow can keep a scoped Cloudflare token in an encrypted, HttpOnly, Secure cookie for up to 15 minutes. It is bound to the signed-in owner, account, and organization and scoped to domain-management requests. Disconnect removes that browser cookie.</p><p>Connect with Cloudflare uses a separate encrypted, HttpOnly authorization-state cookie for up to ten minutes. After approval, credentials are stored encrypted in the installation’s D1 database and renewed automatically until disconnected or revoked. <a href="/docs/cloudflare-connection/">Connection details</a>.</p><h2>Your controls</h2><p>You can manage cookies and site storage in your browser. Blocking authentication cookies may prevent sign-in to an Access-protected installation. Use the Analytics settings control in the footer to allow or decline optional measurement. Declining does not restrict downloads or documentation.</p><p>Questions? Email <a href="mailto:hello@boxox.dev">hello@boxox.dev</a>. <a href="/privacy/">Read the privacy notice.</a></p>`,'LEGAL')},
 '/license/':{title:'Box Ox license — FSL-1.1-MIT application, MIT SDK & CLI',description:'Understand the Box Ox application’s Functional Source License with MIT conversion, and the separate MIT licenses for the SDK and CLI.',body:prosePage('Source available.<br>Clear license terms.','The application and developer tools use different licenses.',`<h2>Box Ox application: FSL-1.1-MIT</h2><p>The published application uses the Functional Source License, Version 1.1, MIT Future License. It permits internal use and other permitted purposes, while restricting competing commercial products and services.</p><p>Each version becomes available under MIT two years after that version was made available. This summary does not replace the license text.</p><p>${button('Read the full application license','/license.txt','secondary')}</p><h2>SDK and CLI: MIT</h2><p>The @boxox/mail SDK and Box Ox CLI are separately MIT licensed. Their downloaded packages contain the applicable license notices. Bundled third-party dependencies retain their own notices.</p><h2>Names, logos, and artwork</h2><p>The Box Ox name and mascot identify this project. Keep applicable notices when redistributing assets and do not imply endorsement or official status for an independent product or service. Cloudflare’s names and marks are owned by Cloudflare.</p><h2>Licensing questions</h2><p>Email <a href="mailto:hello@boxox.dev?subject=Licensing%20question">hello@boxox.dev</a> if you need clarification or want to discuss a use outside the published license.</p>`,'LICENSE')},
 '/releases/':{title:'Box Ox releases — Application, CLI, SDK & agent skill',description:'Release notes and direct-download versions for the self-hosted Box Ox app, typed SDK, standalone CLI, and email integration skill.',body:`<section class="page-hero container">${eyebrow('RELEASES')}<h1>Shipping your ox.</h1><p>Versioned downloads and notes for the app and developer tools.</p></section>${releaseSection()}<section class="container requirement-strip"><strong>Box Ox ${APP_VERSION}:</strong> Requested mailbox permissions, visible approval progress, and recoverable connection errors. <a href="/docs/releases/${APP_VERSION}/">Read release notes →</a></section>${prosePage(`Box Ox ${APP_VERSION}`,`Released ${new Date(RELEASE_DATE).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'})}.`,`<h2>What’s included today</h2><ul><li>Cloudflare-hosted mail client and transactional email API.</li><li>Owner-only administration routes, webhook signing secrets encrypted at rest, and a signing secret separate from the agent credential secret (2.4.6).</li><li>Scoped developer keys, templates, message logs, and signed webhooks.</li><li>OAuth/MCP and grant-limited agent access, with durable change feeds, message claims, and idempotent acknowledgements for agents that resume work (2.4.0).</li><li>Sending and receiving domain setup with DNS previews, explicit MX replacement confirmation, and corrected Cloudflare settings permissions (2.4.7).</li><li>MCP requests with exact mailbox permissions and approval progress (2.4.8).</li><li>Later-domain onboarding without reopening completed setup.</li><li>Mailbox copies of successful API sends, visible in Sent. Received replies appear in Inbox.</li><li>Direct CLI, SDK, and agent-skill downloads.</li></ul><h2>Verification and limits</h2><p>The unchanged 2.4.0 source installed in a fresh Workers Free account without domains: deployment, owner sign-in, and empty app pages passed, and the agent removal procedure later removed that installation. Mail delivery, populated-mail recovery, and Free throughput have not been recorded on a fresh account. Each installer must configure Access and mail domains and verify their own mail round trip. One-click installation is not claimed.</p><p>The release is unsigned. Same-site SHA-256 checksums check download consistency; they are not an independent maintainer signature. Withdrawn source ZIPs are identified in their versioned manifests; 2.4.5 and later remain downloadable.</p><p><a href="/downloads/v${APP_VERSION}/release.json">Versioned release metadata</a> · <a href="/downloads/v${APP_VERSION}/SHA256SUMS.txt">Versioned checksums</a> · <a href="/docs/releases/2.0.0/">2.0.0 release notes</a></p>`,'RELEASE DETAILS',2)}${cta}`},
 '/brand/':{title:'Box Ox brand assets — Logos, mascot & usage notes',description:'Download official Box Ox mascot illustrations, logos, and the character reference sheet for referring to the project and building integrations.',body:prosePage('Meet your ox.','Navy hoodie. Orange horns. A bag full of mail.',`<img class="brand-sheet" src="/brand/character-sheet.webp" width="1448" height="1086" loading="lazy" alt="Box Ox character reference showing front, side, and back views, an expression, mail satchel, and envelope"><h2>Brand download</h2><p>The bundle contains the Box Ox head mark, existing logo assets, new website illustrations, and the character reference sheet.</p><p>${button('Download brand assets',`/downloads/boxox-brand-assets-${BRAND_ASSETS_VERSION}.zip`,'primary','download')}</p><h2>Keep it recognizable</h2><p>Use the supplied proportions and colors. Give the mascot room around its horns and tail. Do not stretch the artwork, remove the project’s identity, or use it to suggest that a separate service is operated or endorsed by Box Ox or Cloudflare.</p><p>For other uses, email <a href="mailto:hello@boxox.dev">hello@boxox.dev</a>. See the <a href="/license/">license page</a> and the notices included in the bundle.</p>`,'BRAND ASSETS')},
};

export function renderSite(dist='apps/site/dist', {documentation=[]} = {}) {
  pages['/requirements/']={title:requirements.title,description:requirements.description,body:prosePage(requirements.heading,requirements.intro,requirements.content,'REQUIREMENTS')};
  pages['/docs/']={title:'Box Ox documentation — Install, send mail & connect agents',description:'Install Box Ox on Cloudflare, send your first message, and configure templates, agents, processing, and domain monitoring.',body:docsPage('/docs/','Box Ox documentation','Install your ox. Send your first message. Build from there.',docsHome),docs:true};
  for(const page of documentation) pages[page.path]={title:page.title,description:page.description,body:docsPage(page.path,page.heading,page.intro,page.content),docs:true};

  const sourceHeaders=readFileSync('apps/site/public/_headers','utf8');
  const basePolicy=sourceHeaders.match(/^  Content-Security-Policy: (.+)$/m)?.[1];
  if(!basePolicy)throw new Error('Missing public-site CSP');
  const pageHeaders=[];
  for(const [path,p] of Object.entries(pages)) {
    const structured=[{'@context':'https://schema.org','@type':'WebSite','@id':ORIGIN+'/#website',url:ORIGIN+'/',name:'Box Ox',description:pages['/'].description}, {'@context':'https://schema.org','@type':'Organization','@id':ORIGIN+'/#publisher',name:'Box Ox',url:ORIGIN+'/',email:'hello@boxox.dev',logo:ORIGIN+'/brand/ox-head-v2.png'}, {'@context':'https://schema.org','@type':'WebPage',url:ORIGIN+path,name:p.title,description:p.description,isPartOf:{'@id':ORIGIN+'/#website'}}];
    if(path==='/')structured.push({'@context':'https://schema.org','@type':'SoftwareApplication',name:'Box Ox',applicationCategory:'DeveloperApplication',operatingSystem:'Cloudflare Workers',softwareVersion:APP_VERSION,url:ORIGIN+'/',downloadUrl:ORIGIN+'/downloads/boxox-v2.zip',license:ORIGIN+'/license/',offers:{'@type':'Offer',price:'0',priceCurrency:'USD'},description:p.description});
    const json=JSON.stringify(structured).replaceAll('<','\\u003c');
    const hash=createHash('sha256').update(json).digest('base64');
    const policy=basePolicy.replace("script-src 'self'", "script-src 'self' 'sha256-"+hash+"'"+(siteConfig.googleAnalyticsMeasurementId?' https://www.googletagmanager.com':''))
      .replace("img-src 'self'", "img-src 'self'"+(siteConfig.googleAnalyticsMeasurementId?' https://www.google-analytics.com':''))
      .replace("form-action 'none'", path==='/contact/'?"form-action 'self'":"form-action 'none'")
      .replace("connect-src 'self'", "connect-src 'self'"+(siteConfig.googleAnalyticsMeasurementId?' https://www.google-analytics.com https://region1.google-analytics.com https://www.googletagmanager.com':''));
    pageHeaders.push(`${path}\n  Cache-Control: no-cache\n  Content-Security-Policy: ${policy}\n`);
    const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(p.title)}</title><meta name="description" content="${esc(p.description)}"><meta name="theme-color" content="#ffffff"><meta name="boxox-release-version" content="${APP_VERSION}">${siteConfig.googleSiteVerification?`<meta name="google-site-verification" content="${esc(siteConfig.googleSiteVerification)}">`:""}${siteConfig.googleAnalyticsMeasurementId?`<meta name="boxox-analytics-id" content="${esc(siteConfig.googleAnalyticsMeasurementId)}"><script src="/analytics.js" defer></script>`:""}<link rel="canonical" href="${ORIGIN+path}"><meta property="og:type" content="website"><meta property="og:site_name" content="Box Ox"><meta property="og:title" content="${esc(p.title)}"><meta property="og:description" content="${esc(p.description)}"><meta property="og:url" content="${ORIGIN+path}"><meta property="og:image" content="${ORIGIN}/brand/social-card.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(p.title)}"><meta name="twitter:description" content="${esc(p.description)}"><meta name="twitter:image" content="${ORIGIN}/brand/social-card.png"><link rel="icon" href="/brand/ox-head-v2.png" type="image/png"><link rel="preload" href="/fonts/inter-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/style.css">${p.docs?'<link rel="stylesheet" href="/docs.css">':''}<script src="/site.js" defer></script>${path==='/downloads/'?'<script src="/agent-install.js" defer></script>':''}<script type="application/ld+json">${json}</script></head><body${p.docs?' class="docs-site"':''}>${p.docs?docsHeader(mark):header(path.slice(1,-1))}<main id="main">${p.body}</main>${p.docs?'':footer}${siteConfig.googleAnalyticsMeasurementId?analyticsConsent:""}</body></html>`;
    const directory=resolve(dist,'.'+path);mkdirSync(directory,{recursive:true});writeFileSync(resolve(directory,'index.html'),humanLinks(html));
  }
  // Each HTML page permits its own structured-data hash. A single allowlist
  // grows past Cloudflare's 2,000-character header-line limit as docs expand.
  const generatedHeaders=sourceHeaders.replace(/^  Content-Security-Policy: .+\n/m,'')+'\n'+pageHeaders.join('\n');
  if(generatedHeaders.split('\n').some(line=>line.length>2000))throw new Error('Header line exceeds Cloudflare limit');
  writeFileSync(resolve(dist,'_headers'),generatedHeaders);
  const urls=[...new Set([...Object.keys(pages),'/setup/'])];
  writeFileSync(resolve(dist,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map(path=>`<url><loc>${ORIGIN+path}</loc></url>`).join('')}</urlset>\n`);
  writeFileSync(resolve(dist,'robots.txt'),`User-agent: *\nAllow: /\n${RELEASES.map(version=>`Disallow: /downloads/v${version}/\n`).join('')}Disallow: /downloads/boxox-\nSitemap: ${ORIGIN}/sitemap.xml\n`);
  console.log(`Rendered ${Object.keys(pages).length} public pages with metadata, structured data, and sitemap`);
}
if(process.argv[1]===import.meta.filename)renderSite(process.argv[2]);
